service.method:

SELECT COUNT( * ) - 1 
	  FROM SGWGL GWGL 
	   INNER JOIN SGWLN GWLN 
	       ON GWGL.HOUSE_CODE = GWLN.HOUSE_CODE 
	       AND GWGL.COMPANY_CODE = GWLN.COMPANY_CODE 
	       AND GWGL.APP_NO = GWLN.APP_NO 
	       AND GWGL.APP_NO_SEQ = GWLN.APP_NO_SEQ 
	 WHERE GWGL.HOUSE_CODE = ${session.HOUSE_CODE} 
	       AND GWGL.COMPANY_CODE = ${SEPOA_APPROVAL_S_COMPANY_CODE} 
	       AND GWGL.APP_NO = ${APP_NO} 
	       AND GWGL.APP_NO_SEQ = ${APP_NO_SEQ} 
	       AND GWLN.APP_TYPE = ${APP_TYPE} 
           AND CONVERT(INT, ISNULL(GWGL.CURRENT_STAGE,'999')) <= CONVERT(INT, ISNULL(GWLN.APP_STAGE,'999'))


UPDATE SGWGL 
       SET APP_STATUS = ${APP_STATUS} 
     , CURRENT_STAGE  = ${CURRENT_STAGE}  
     , CHANGE_DATE    = ${current.DATE}
     , CHANGE_TIME    = ${current.TIME}
     , CHANGE_USER_ID = ${session.ID}  
 WHERE HOUSE_CODE = ${session.HOUSE_CODE} 
       AND COMPANY_CODE = ${SEPOA_APPROVAL_S_COMPANY_CODE} 
       AND APP_NO = ${APP_NO} 
       AND APP_NO_SEQ = ${APP_NO_SEQ}


UPDATE SGWLN 
       SET APP_LINE_STATUS = ${APP_LINE_STATUS}
     , APP_DEVICE          = ${APP_DEVICE}
     , CHANGE_DATE         = ${current.DATE}
     , CHANGE_TIME         = ${current.TIME}
     , CHANGE_USER_ID      = ${session.ID}  
     , ACCEPT_USER_ID      = ${session.ID}
     , ACCEPT_DATE         = ${current.DATE} 
     , ACCEPT_TIME         = ${current.TIME} 
     , ACCEPT_REASON       = ${ACCEPT_REASON} 
 WHERE HOUSE_CODE = ${session.HOUSE_CODE} 
       AND COMPANY_CODE = ${SEPOA_APPROVAL_S_COMPANY_CODE} 
       AND APP_NO = ${APP_NO} 
       AND APP_NO_SEQ = ${APP_NO_SEQ} 
       AND APP_LINE_SEQ = ${APP_LINE_SEQ}


UPDATE SGWLN 
       SET APP_LINE_STATUS = ${APP_LINE_STATUS}
     , APP_DEVICE          = ${APP_DEVICE}
     , CHANGE_DATE         = ${current.DATE}
     , CHANGE_TIME         = ${current.TIME}
     , CHANGE_USER_ID      = ${session.ID}  
 WHERE HOUSE_CODE = ${session.HOUSE_CODE} 
       AND COMPANY_CODE = ${SEPOA_APPROVAL_S_COMPANY_CODE} 
       AND APP_NO = ${APP_NO} 
       AND APP_NO_SEQ = ${APP_NO_SEQ} 
       AND APP_STAGE = ${APP_STAGE}
